from collections import Counter

class Solution:
    def findMatrix(self, nums: list[int]) -> list[list[int]]:
        count = Counter(nums)
        result = []
        for num, freq in count.items():
            for i in range(freq):
                if i >= len(result):
                    result.append([])
                result[i].append(num)
        return result

